WITH flattened AS (SELECT id, service, host, log_ts, level, latency_ms, status_code, k, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) e AS k, value), enriched AS (SELECT id, service, host, log_ts, level, latency_ms, status_code, k, value, MAX(latency_ms) OVER (PARTITION BY k ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) AS latency_ms_max_15m, CORR(status_code, latency_ms) OVER (PARTITION BY k) AS corr_status_code_latency_ms FROM flattened), cleaned AS (SELECT service, host, level, latency_ms, status_code, k, value, latency_ms_max_15m, corr_status_code_latency_ms, TRIM(level) AS clean_level FROM enriched WHERE log_ts > TIMESTAMP '2025-06-01 06:00:00' AND service IN ('auth', 'checkout')) SELECT k, CASE WHEN corr_status_code_latency_ms >= 0.62 THEN 'HIGH' ELSE 'LOW' END AS corr_status_code_latency_ms_tier, PERCENTILE_APPROX(status_code, ARRAY(0.25, 0.5, 0.75)) AS status_code_quartiles, SIZE(COLLECT_SET(level)) AS num_levels, COUNT_IF(k = 'region') AS region_events, APPROX_PERCENTILE(latency_ms_max_15m, ARRAY(0.25, 0.5, 0.75)) AS latency_ms_max_15m_quartiles, DENSE_RANK() OVER (PARTITION BY k ORDER BY COUNT_IF(k = 'region') DESC) AS region_events_dense_rank FROM cleaned GROUP BY k, CASE WHEN corr_status_code_latency_ms >= 0.62 THEN 'HIGH' ELSE 'LOW' END HAVING num_levels < 1;
